class Solution:
    def minOperations(self, nums):
        arr = list(nums)
        ops = 0
        for i in range(1, len(arr)):
            if arr[i] <= arr[i - 1]:
                need = arr[i - 1] + 1 - arr[i]
                arr[i] += need
                ops += need
        return ops

