class Solution {
public:
    int minOperations(vector<int>& nums) {
        vector<int> arr = nums;
        int ops = 0;
        for (int i = 1; i < (int)arr.size(); i++) {
            if (arr[i] <= arr[i - 1]) {
                int need = arr[i - 1] + 1 - arr[i];
                arr[i] += need;
                ops += need;
            }
        }
        return ops;
    }
};

